function stats(){const c=classes[s.class],m=scores().map(mod),dex=Math.min(m[1],c.maxDex),bab=s.class==='Guerrero'?level():s.class==='Pícaro'?Math.floor(level()*.75):Math.floor(level()/2);return{bab,hp:Math.max(1,c.hp+m[2])+(has('Dureza')?3:0)+(s.class==='Mago'?3:0)+(level()-1)*Math.max(1,c.hp/2+1+m[2]),ac:10+c.armor+c.shield+dex+(campaignCape?1:0),touch:10+dex+(campaignCape?1:0),flat:10+c.armor+c.shield+Math.min(0,dex)+(campaignCape?1:0),init:m[1]+(has('Iniciativa mejorada')?4:0),attack:bab+m[0]+(has('Soltura con el arma')?1:0),ranged:bab+m[1],damage:m[0]<0?m[0]:Math.floor(m[0]*(s.class==='Mago'?1.5:1)),saves:c.saves.map((v,i)=>(v===2?2+Math.floor(level()/2):Math.floor(level()/3))+m[[2,1,4][i]]+(has(['Gran fortaleza','Reflejos rápidos','Voluntad de hierro'][i])?2:0))};}
function skillTotal(i){const k=skills[i];return(s.ranks[i]||0)+mod(scores()[k[1]])+k[3]*classes[s.class].acp+((raceData[s.race]?.skill||'').split('|').includes(k[0])?2:0)+(has('Alerta')&&['Avistar','Escuchar'].includes(k[0])?2:0)+(k[0]==='Saltar'&&s.race==='Enano'?-6:0)}
function persist(explicit=false){try{localStorage.setItem(KEY,JSON.stringify(s));document.getElementById('status').textContent=explicit?'Personaje guardado en este navegador.':'Cambios guardados en este navegador.'}catch{document.getElementById('status').textContent='No se pudo guardar. Mantén esta ventana abierta e imprime la hoja.'}}
function notifyParent(){if(window.parent!==window)window.parent.postMessage({type:'character-saved'},location.origin)}
function identity(){return `<div class="fields"><label class="full">Nombre del personaje<input id="name" maxlength="40" placeholder="¿Cómo te recordarán?" value="${esc(s.name)}" autocomplete="off"></label><label>Raza<select id="race">${['Humano','Elfo','Enano'].map(x=>`<option ${s.race===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Alineamiento<select id="alignment">${['Legal bueno','Neutral bueno','Caótico bueno','Legal neutral','Neutral','Caótico neutral','Legal maligno','Neutral maligno','Caótico maligno'].map(x=>`<option ${s.alignment===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Clase</label><div class="class-grid">${Object.entries(classes).map(([k,v])=>`<button class="class-card ${s.class===k?'selected':''}" data-class="${k}" aria-pressed="${s.class===k}"><div class="class-icon">${v.icon}</div><strong>${k}</strong><span>${v.tag}</span></button>`).join('')}</div><p class="note">${raceText()}</p><div class="section-head"><h2>Atributos</h2><span class="counter">${28-spent()} / 28 puntos disponibles</span></div><div class="abilities">${scores().map((v,i)=>`<div class="ability"><label>${short[i]}</label><span class="score">${v}</span><span class="modifier">${sign(mod(v))} modificador</span><div class="stepper"><button data-ability="${i}" data-delta="-1" aria-label="Reducir ${names[i]}" ${s.base[i]<=8?'disabled':''}>−</button><small>${s.base[i]}</small><button data-ability="${i}" data-delta="1" aria-label="Aumentar ${names[i]}" ${s.base[i]>=18||costs[s.base[i]+1]-costs[s.base[i]]>28-spent()?'disabled':''}>+</button></div></div>`).join('')}</div><p class="mini">Valor grande: total con raza · Valor entre botones: base. Subir sobre 14 cuesta más puntos.</p><button id="preset" class="text-button">Restablecer atributos recomendados de ${s.class.toLowerCase()}</button><p class="mini">Cambiar clase o atributos reinicia los rangos de habilidades para repartirlos nuevamente.</p><label>Historia personal <span class="mini">· opcional</span><textarea id="bio" maxlength="1800" placeholder="¿Qué dejaste atrás? ¿Por qué responderías a la carta?">${esc(s.bio)}</textarea></label>`}
function raceText(){return raceData[s.race]?.text||'Raza no disponible.'}
function skillView(){return `<div class="section-head"><h2>Lo que sabes hacer</h2><span class="counter">${pool()-skillSpent()} / ${pool()} puntos</span></div><p class="note">Clase: 1 punto por rango, máximo ${level()+3}. Transclásea: 1 punto por ½ rango, máximo ${(level()+3)/2}. El total incluye atributo, raza, dotes y penalización de armadura cuando corresponde. * Requiere entrenamiento.</p><p class="mini">Selección de habilidades para esta campaña. Los bonos situacionales se detallan en la hoja final.</p><div class="skill-list">${skills.map((k,i)=>`<div class="skill-row"><div>${k[0]}${k[4]?' *':''}<small>${short[k[1]]} · ${inClass(i)?'De clase':'Transclásea'}</small></div><div class="stepper"><button data-skill="${i}" data-delta="-1" aria-label="Quitar rango de ${k[0]}" ${!s.ranks[i]?'disabled':''}>−</button><span>${s.ranks[i]||0}</span><button data-skill="${i}" data-delta="1" aria-label="Añadir rango de ${k[0]}" ${pool()-skillSpent()<1||(s.ranks[i]||0)>=skillCap(i)?'disabled':''}>+</button></div><b>${k[4]&&!s.ranks[i]?'—':sign(skillTotal(i))}</b></div>`).join('')}</div>`}
function equipView(){return `<h2>Dotes y equipo</h2><p class="note">Una dote al nivel 1${level()>=3?", otra al nivel 3":""}${s.race==='Humano'?', una adicional por humano':''}${s.class==='Guerrero'?` y ${1+Math.floor(level()/2)} adicional(es) de combate por guerrero`:''}. Las opciones respetan los requisitos y no se repiten.</p>${Array.from({length:countFeats()},(_,i)=>`<label class="feat">${combatSlot(i)?'Dote adicional de guerrero':'Dote '+(i+1)}<select data-feat="${i}"><option value="">Elige una dote</option>${Object.entries(feats).filter(([k,v])=>(!v.req||v.req())&&(!(combatSlot(i))||v.combat)&&(!s.feats.includes(k)||s.feats[i]===k)).map(([k])=>`<option ${s.feats[i]===k?'selected':''}>${k}</option>`).join('')}</select><span class="mini">${feats[s.feats[i]]?.text||'Selecciona una opción disponible.'}</span></label>`).join('')}<div class="section-head"><h2>Equipo del viajero</h2><span class="counter">Paquete de campaña</span></div><p class="note">${classes[s.class].gear}</p><div class="line"><span>Arma · ${classes[s.class].weapon}</span><b>${classes[s.class].damage} ${sign(stats().damage)}</b></div><div class="line"><span>Crítico</span><b>${classes[s.class].critical}</b></div><div class="line"><span>Bono de armadura / escudo</span><b>+${classes[s.class].armor} / +${classes[s.class].shield}</b></div><div class="line"><span>Penalización de armadura a habilidades</span><b>${classes[s.class].acp}</b></div><p class="note">Equipo entregado por la campaña; sin compra ni gestión de carga en esta etapa.</p><h3>Rasgos de clase</h3><p class="note">${classes[s.class].features}</p>${s.class==='Mago'?magic():''}`}
function magic(){const intel=scores()[3],m=mod(intel),slots=intel>=11?level()+(m>=1?1:0):0;return `<h3>Magia del viajero</h3><p class="note">Mago generalista de nivel ${level()}. CD de conjuros de nivel 1: ${11+m}. Espacios de nivel 1: ${slots}.</p><p class="note">En este tramo jugable: Proyectil mágico (1d4+1, impacto automático) y Armadura de mago (+4 CA durante el encuentro). Usan una reserva compartida de ${slots} usos, recuperada al descansar.</p><p class="mini">Adaptación para este primer tramo: todavía no se elige la preparación individual de cada espacio. Los demás conjuros del libro no están implementados en combate.</p>`}
function sheet(){const st=stats(),c=classes[s.class],problems=issues();return `<h2>${esc(s.name.trim()||'Tu personaje')}</h2><p class="note">${s.race} · ${s.class} 1 · ${esc(s.alignment)} · Tamaño mediano</p><div class="alert">${problems.length?'Por completar: '+problems.join('; ')+'.':'Personaje listo para el inicio de la campaña.'}</div><div class="stats">${[[st.hp,'Puntos de golpe','Máximo al nivel 1'],[st.ac,'Clase de armadura',`Toque ${st.touch} · Desprevenido ${st.flat}`],[sign(st.init),'Iniciativa','DES + dotes'],[sign(st.saves[0]),'Fortaleza','CON + base + dotes'],[sign(st.saves[1]),'Reflejos','DES + base + dotes'],[sign(st.saves[2]),'Voluntad','SAB + base + dotes']].map(x=>`<div class="stat"><b>${x[0]}</b><span>${x[1]}</span><small>${x[2]}</small></div>`).join('')}</div><div class="line"><span>Atributos</span><b>${scores().map((v,i)=>short[i]+' '+v).join(' · ')}</b></div><div class="line"><span>${c.weapon} · Ataque</span><b>${sign(st.attack)}</b></div><div class="line"><span>Daño / crítico</span><b>${c.damage} ${sign(st.damage)} / ${c.critical}</b></div><div class="line"><span>Ataque base / presa</span><b>${sign(st.bab)} / ${sign(st.bab+mod(scores()[0]))}</b></div><div class="line"><span>Ataque a distancia (sin arma equipada)</span><b>${sign(st.ranged)}</b></div><div class="line"><span>Velocidad</span><b>${s.race==='Enano'?6:9} m</b></div><h3 style="margin-top:25px">Dotes y capacidades</h3><p class="note">${s.feats.filter(Boolean).map(esc).join(' · ')||'Dotes pendientes'}</p><p class="note">${c.features}${level()>=2&&s.class==='Pícaro'?' Evasión: una salvación de Reflejos exitosa contra un efecto que permite mitad de daño evita todo el daño.':''}</p><p class="note">${raceText()}</p>${s.race==='Enano'?'<p class="mini">Bonos situacionales no sumados: +4 contra embestida/derribo si está en el suelo; +1 al ataque contra orcos y trasgoides; +4 de esquiva contra gigantes; afinidad con piedra (+2 Buscar sobre mampostería), +2 Tasación/Artesanía de piedra o metal. Familiaridad con armas enanas.</p>':s.race==='Elfo'?'<p class="mini">Competencia racial: espada larga, estoque y arcos largos/cortos (incluidos compuestos). Puede detectar puertas secretas al pasar a 1,5 m.</p>':''}<h3>Habilidades entrenadas</h3>${skills.map((k,i)=>s.ranks[i]?`<div class="line"><span>${k[0]} · ${s.ranks[i]} rangos</span><b>${sign(skillTotal(i))}</b></div>`:'').join('')||'<p class="note">Aún no repartes puntos.</p>'}<h3 style="margin-top:25px">Equipo</h3><p class="note">${c.gear}${campaignCape?" Capa de la Vigilia equipada: +1 CA de desvío.":""}</p>${s.class==='Mago'?magic():''}${s.bio?`<h3>Historia personal</h3><p class="note" style="white-space:pre-wrap">${esc(s.bio)}</p>`:''}<h3 style="margin-top:25px">Prueba tus dados</h3><p class="mini">Tiradas de práctica. No resuelven encuentros ni consumen recursos.</p><div class="rolls"><button data-roll="Ataque" data-bonus="${st.attack}">⚄ Ataque</button><button data-roll="Iniciativa" data-bonus="${st.init}">Iniciativa</button>${st.saves.map((v,i)=>`<button data-roll="${['Fortaleza','Reflejos','Voluntad'][i]}" data-bonus="${v}">${['Fortaleza','Reflejos','Voluntad'][i]}</button>`).join('')}</div><div id="roll-result" role="status"></div><button id="print" class="quiet">Imprimir hoja / Guardar PDF</button> <button id="read-final" class="text-button">Leer el prólogo ↗</button>`}
function updateHero(){document.getElementById('hero-name').textContent=s.name.trim()||'Un nombre. Un destino.';document.getElementById('hero-type').textContent=s.race+' · '+s.class}
function render(){document.querySelector('.edition').textContent='D&D 3.5 · NIVEL '+level();document.querySelector('.level b').textContent=level();document.querySelector('.level small').textContent=level()===4?'Hito: cautivos liberados':level()===3?'Hito: llegada al monasterio':level()===2?'Hito: criptas resueltas':'Inicio de campaña';updateHero();document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'step':'false')});document.getElementById('content').innerHTML=({identity,skills:skillView,equipment:equipView,sheet}[tab])();document.getElementById('next').textContent=tab==='sheet'?'Guardar personaje':'Continuar →';bind()}
function changed(){normalize();render();persist()}
function bind(){const e=id=>document.getElementById(id);for(const id of ['name','bio'])if(e(id))e[id==='name'?'oninput':'oninput']=ev=>{s[id]=ev.target.value;updateHero();persist()};if(e('alignment'))e('alignment').onchange=ev=>{s.alignment=ev.target.value;persist()};if(e('race'))e('race').onchange=ev=>{s.race=ev.target.value;s.ranks={};changed()};document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{if(s.class===b.dataset.class)return;s.class=b.dataset.class;s.subclass=(subclassData[s.class]||[])[0][0];s.base=[...classes[s.class].pres];s.ranks={};s.feats=[];changed()});document.querySelectorAll('[data-subclass]').forEach(b=>b.onclick=()=>{s.subclass=b.dataset.subclass;changed()});document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{s.gender=b.dataset.gender;changed()});document.querySelectorAll('[data-ability]').forEach(b=>b.onclick=()=>{const i=+b.dataset.ability,value=s.base[i]+(+b.dataset.delta);if(value<8||value>18||spent()-costs[s.base[i]]+costs[value]>28)return;s.base[i]=value;s.ranks={};changed()});if(e('preset'))e('preset').onclick=()=>{s.base=[...classes[s.class].pres];s.ranks={};changed()};document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const i=+b.dataset.skill,delta=+b.dataset.delta,step=inClass(i)?1:.5,value=(s.ranks[i]||0)+delta*step;if(value<0||value>skillCap(i)||(delta>0&&pool()-skillSpent()<1))return;s.ranks[i]=value;changed()});document.querySelectorAll('[data-feat]').forEach(b=>b.onchange=()=>{s.feats[+b.dataset.feat]=b.value;changed()});document.querySelectorAll('[data-roll]').forEach(b=>b.onclick=()=>{const n=die20();e('roll-result').textContent=`${b.dataset.roll}: ${n} ${sign(+b.dataset.bonus)} = ${n+(+b.dataset.bonus)}${b.dataset.roll==='Ataque'&&n===20?' · Amenaza de crítico (requiere confirmar)':b.dataset.roll==='Ataque'&&n===1?' · Fallo automático':''}`});if(e('print'))e('print').onclick=()=>window.print();if(e('read-final'))e('read-final').onclick=openStory}
function decorateCharacterPreviews(v){const cape=wearingPortraitCape(),portrait=portraitSource(),source=window.CenizasAvatar?.source?.(s,{cape})||portrait,title=`${s.race} · ${s.class} · ${v.subclassLabel} · ${s.gender}`,gear=cape?'Capa de la Vigilia':classes[s.class]?.weapon||'Equipo de campaña';document.querySelectorAll('.character-visual-preview').forEach(el=>{el.innerHTML=`<div class="preview-raster-surface"><img class="preview-raster-backdrop" src="${portrait}" alt="" loading="eager" decoding="async" onerror="this.onerror=null;this.src='traveler-portrait.png'"><div class="preview-character-stage ${esc(v.visual)} ${esc(v.genderClass)} ${esc(v.raceClass)} ${cape?'cape':''}" aria-hidden="true"><span class="preview-character-aura"></span><img class="preview-character-render" src="${source}" alt="" loading="eager" decoding="async" onerror="this.onerror=null;this.src='traveler-portrait.png'"><span class="preview-character-equip"></span></div><div class="preview-character-kicker">RENDER JUGABLE</div><div class="preview-raster-copy"><strong>${esc(s.class)} · ${esc(v.subclassLabel)}</strong><small>${esc(s.race)} · ${esc(s.gender)} · ${esc(gear)}</small></div></div>`;el.setAttribute('role','img');el.setAttribute('aria-label',title)})}
function stripPersonalHistory(){const had=Boolean(s.bio);s.bio='';document.getElementById('bio')?.closest('label')?.remove();document.querySelectorAll('h3').forEach(h=>{if(h.textContent.trim()==='Historia personal'){const next=h.nextElementSibling;h.remove();next?.remove()}});return had}
const renderWithPortraitPreviews=render;render=function(){const progressed=autoApplyProgression();renderWithPortraitPreviews();decorateCharacterPreviews(visualProfile());const removed=stripPersonalHistory();if(progressed||removed)persist()}
function die20(){const a=new Uint32Array(1),limit=4294967280;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%20+1}
function openStory(){document.getElementById('story').showModal()}
function identity(){const v=visualProfile();return `<div class="fields"><label class="full">Nombre del personaje<input id="name" maxlength="40" placeholder="¿Cómo te recordarán?" value="${esc(s.name)}" autocomplete="off"></label><label>Raza<select id="race">${Object.keys(raceData).map(x=>`<option ${s.race===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Alineamiento<select id="alignment">${['Legal bueno','Neutral bueno','Caótico bueno','Legal neutral','Neutral','Caótico neutral','Legal maligno','Neutral maligno','Caótico maligno'].map(x=>`<option ${s.alignment===x?'selected':''}>${x}</option>`).join('')}</select></label></div><section class="archetype-builder"><div class="builder-copy"><span class="eyebrow">IDENTIDAD VISUAL</span><h2>Elige quién cruza el Umbral</h2><p class="note">La clase define la silueta y el equipo; la subclase añade un sello propio; el género cambia los detalles de presentación sin modificar tus atributos.</p></div><div class="character-visual-preview ${v.visual} ${v.genderClass} ${v.raceClass}" style="--accent:${v.accent}" role="img" aria-label="${esc(s.race+' · '+s.class+' · '+v.subclassLabel+' · '+s.gender)}"><div class="visual-halo"></div><div class="visual-sigil">${v.sigil}</div><div class="visual-figure"><i></i><b></b></div><strong>${esc(s.class)} · ${esc(v.subclassLabel)}</strong><small>${esc(s.race)} · ${esc(s.gender)} · ${v.genderSigil}</small></div></section><label>Clase</label><div class="class-grid">${Object.entries(classes).map(([k,c])=>`<button type="button" class="class-card ${s.class===k?'selected':''}" data-class="${k}" aria-pressed="${s.class===k}"><div class="class-icon">${c.icon}</div><strong>${k}</strong><span>${c.tag}</span></button>`).join('')}</div><p class="note">Elige una clase para cambiar tus atributos recomendados, equipo y capacidades.</p><label>Subclase</label><div class="subclass-grid">${(subclassData[s.class]||[]).map(x=>`<button type="button" class="subclass-card ${s.subclass===x[0]?'selected':''}" data-subclass="${x[0]}" aria-pressed="${s.subclass===x[0]}" style="--accent:${x[4]}"><span>${x[2]}</span><strong>${x[1]}</strong><small>${x[0]==='Guardia'?'Protección y control':x[0]==='Berserker'?'Fuerza y riesgo':x[0]==='Sombra'?'Sigilo y golpes precisos':x[0]==='Explorador'?'Rastreo y supervivencia':x[0]==='Arcanista'?'Control de la magia':'Resonancia del Umbral'}</small></button>`).join('')}</div><label>Género</label><div class="gender-grid">${genderData.map(x=>`<button type="button" class="gender-card ${s.gender===x[0]?'selected':''}" data-gender="${x[0]}" aria-pressed="${s.gender===x[0]}"><span>${x[2]}</span><strong>${x[0]}</strong></button>`).join('')}</div><p class="note">${raceText()}</p><div class="section-head"><h2>Atributos</h2><span class="counter">${28-spent()} / 28 puntos disponibles</span></div><div class="abilities">${scores().map((value,i)=>`<div class="ability"><label>${short[i]}</label><span class="score">${value}</span><span class="modifier">${sign(mod(value))} modificador</span><div class="stepper"><button data-ability="${i}" data-delta="-1" aria-label="Reducir ${names[i]}" ${s.base[i]<=8?'disabled':''}>−</button><small>${s.base[i]}</small><button data-ability="${i}" data-delta="1" aria-label="Aumentar ${names[i]}" ${s.base[i]>=18||costs[s.base[i]+1]-costs[s.base[i]]>28-spent()?'disabled':''}>+</button></div></div>`).join('')}</div><p class="mini">Valor grande: total con raza · Valor entre botones: base. Subir sobre 14 cuesta más puntos.</p><button id="preset" class="text-button" type="button">Restablecer atributos recomendados de ${s.class.toLowerCase()}</button><p class="mini">Cambiar clase o atributos reinicia los rangos de habilidades para repartirlos nuevamente.</p><label>Historia personal <span class="mini">· opcional</span><textarea id="bio" maxlength="1800" placeholder="¿Qué dejaste atrás? ¿Por qué responderías a la carta?">${esc(s.bio)}</textarea></label>`}
function sheet(){const st=stats(),c=classes[s.class],v=visualProfile(),problems=[];if(!s.name.trim())problems.push('pon un nombre');const statRows=[[st.hp,'Puntos de golpe','Máximo al nivel 1'],[st.ac,'Clase de armadura','Toque '+st.touch+' · Desprevenido '+st.flat],[sign(st.init),'Iniciativa','DES + dotes'],[sign(st.saves[0]),'Fortaleza','CON + base + dotes'],[sign(st.saves[1]),'Reflejos','DES + base + dotes'],[sign(st.saves[2]),'Voluntad','SAB + base + dotes']].map(x=>'<div class="stat"><b>'+x[0]+'</b><span>'+x[1]+'</span><small>'+x[2]+'</small></div>').join('');const saveRows=st.saves.map((value,i)=>{const label=['Fortaleza','Reflejos','Voluntad'][i];return '<button data-roll="'+label+'" data-bonus="'+value+'">'+label+'</button>'}).join('');const visualNote=s.class==='Mago'?'Tu presencia se lee como magia: foco, túnica y brillo arcano.':s.class==='Pícaro'?'Tu presencia se lee como sigilo: capa ligera y emblema discreto.':'Tu presencia se lee como acero: silueta firme y emblema de guardia.';return `<section class="sheet-identity"><div class="character-visual-preview ${v.visual} ${v.genderClass} ${v.raceClass}" style="--accent:${v.accent}"><div class="visual-halo"></div><div class="visual-sigil">${v.sigil}</div><div class="visual-figure"><i></i><b></b></div><strong>${esc(s.class)} · ${esc(v.subclassLabel)}</strong><small>${esc(s.race)} · ${esc(s.gender)}</small></div><div><h2>${esc(s.name.trim()||'Tu personaje')}</h2><p class="note">${esc(s.race)} · ${esc(s.gender)} · ${esc(s.class)} · ${esc(v.subclassLabel)} · Nivel 1 · ${esc(s.alignment)}</p><p class="note">${visualNote}</p></div></section><div class="alert">${problems.length?'Por completar: '+problems.join('; ')+'.':'Personaje listo para el inicio de la campaña.'}</div><div class="stats">${statRows}</div><div class="line"><span>Atributos</span><b>${scores().map((value,i)=>short[i]+' '+value).join(' · ')}</b></div><div class="line"><span>${c.weapon} · Ataque</span><b>${sign(st.attack)}</b></div><div class="line"><span>Daño / crítico</span><b>${c.damage} ${sign(st.damage)} / ${c.critical}</b></div><div class="line"><span>Velocidad</span><b>${raceData[s.race].speed} m</b></div><h3 style="margin-top:25px">Dotes y capacidades</h3><p class="note">${s.feats.filter(Boolean).map(esc).join(' · ')||'Dotes pendientes'}</p><p class="note">${c.features}</p><h3>Habilidades entrenadas</h3>${skills.map((k,i)=>s.ranks[i]?'<div class="line"><span>'+k[0]+' · '+s.ranks[i]+' rangos</span><b>'+sign(skillTotal(i))+'</b></div>':'').join('')||'<p class="note">Aún no repartes puntos.</p>'}<h3 style="margin-top:25px">Equipo</h3><p class="note">${c.gear}${campaignCape?' Capa de la Vigilia equipada: +1 CA de desvío.':''}</p>${s.class==='Mago'?magic():''}${s.bio?'<h3>Historia personal</h3><p class="note" style="white-space:pre-wrap">'+esc(s.bio)+'</p>':''}<h3 style="margin-top:25px">Prueba tus dados</h3><p class="mini">Tiradas de práctica. No resuelven encuentros ni consumen recursos.</p><div class="rolls"><button data-roll="Ataque" data-bonus="${st.attack}">⚄ Ataque</button><button data-roll="Iniciativa" data-bonus="${st.init}">Iniciativa</button>${saveRows}</div><div id="roll-result" role="status"></div><button id="print" class="quiet" type="button">Imprimir hoja / Guardar PDF</button> <button id="read-final" class="text-button" type="button">Leer el prólogo ↗</button>`}
function updateHero(){const v=visualProfile();document.getElementById('hero-name').textContent=s.name.trim()||'Un nombre. Un destino.';document.getElementById('hero-type').textContent=`${s.race} · ${s.class} · ${v.subclassLabel} · ${s.gender}`;document.querySelector('.portrait')?.setAttribute('data-archetype',`${v.visual} ${v.genderClass} ${v.raceClass}`);document.documentElement.style.setProperty('--hero-accent',v.accent);renderPortrait(v)}
function changed(){const pageTop=window.scrollY,listTop=document.querySelector('.skill-list')?.scrollTop||0;normalizeCharacter();normalize();render();persist();window.scrollTo(0,pageTop);const nextList=document.querySelector('.skill-list');if(nextList)nextList.scrollTop=listTop}
function bind(){const e=id=>document.getElementById(id);for(const id of ['name','bio'])if(e(id))e(id).oninput=ev=>{s[id]=ev.target.value;updateHero();persist()};if(e('alignment'))e('alignment').onchange=ev=>{s.alignment=ev.target.value;persist()};if(e('race'))e('race').onchange=ev=>{s.race=ev.target.value;s.ranks={};changed()};document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{if(s.class===b.dataset.class)return;s.class=b.dataset.class;s.subclass=(subclassData[s.class]||[])[0][0];s.base=[...classes[s.class].pres];s.ranks={};s.feats=[];changed()});document.querySelectorAll('[data-subclass]').forEach(b=>b.onclick=()=>{s.subclass=b.dataset.subclass;changed()});document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{s.gender=b.dataset.gender;changed()});document.querySelectorAll('[data-ability]').forEach(b=>b.onclick=()=>{const i=+b.dataset.ability,value=s.base[i]+(+b.dataset.delta);if(value<8||value>18||spent()-costs[s.base[i]]+costs[value]>28)return;s.base[i]=value;s.ranks={};changed()});if(e('preset'))e('preset').onclick=()=>{s.base=[...classes[s.class].pres];s.ranks={};changed()};document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const i=+b.dataset.skill,delta=+b.dataset.delta,step=inClass(i)?1:.5,value=(s.ranks[i]||0)+delta*step;if(value<0||value>skillCap(i)||(delta>0&&pool()-skillSpent()<1))return;s.ranks[i]=value;changed()});document.querySelectorAll('[data-feat]').forEach(b=>b.onchange=()=>{s.feats[+b.dataset.feat]=b.value;changed()});document.querySelectorAll('[data-roll]').forEach(b=>b.onclick=()=>{const n=die20();e('roll-result').textContent=`${b.dataset.roll}: ${n} ${sign(+b.dataset.bonus)} = ${n+(+b.dataset.bonus)}${b.dataset.roll==='Ataque'&&n===20?' · Amenaza de crítico (requiere confirmar)':b.dataset.roll==='Ataque'&&n===1?' · Fallo automático':''}`});if(e('print'))e('print').onclick=()=>window.print();if(e('read-final'))e('read-final').onclick=openStory}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.getElementById('save').onclick=()=>{persist(true);notifyParent()};document.getElementById('next').onclick=()=>{if(tab==='sheet'){persist(true);notifyParent();return}tab=['identity','skills','equipment','sheet'][['identity','skills','equipment','sheet'].indexOf(tab)+1];render();document.querySelector('nav').scrollIntoView({behavior:'smooth',block:'start'})};document.getElementById('prologue').onclick=openStory;document.getElementById('close-story').onclick=()=>document.getElementById('story').close();document.getElementById('return-character').onclick=()=>document.getElementById('story').close();render();if(saved)document.getElementById('status').textContent='Personaje recuperado de este navegador.';
